using AppCondominio.Modules.SecurityOperations.Infrastructure;using Microsoft.Extensions.Diagnostics.HealthChecks;
namespace AppCondominio.Api.Health;public sealed class SecurityOperationsDatabaseHealthCheck(SecurityOperationsDbContext dbContext):IHealthCheck{public async Task<HealthCheckResult> CheckHealthAsync(HealthCheckContext context,CancellationToken cancellationToken=default){try{return await dbContext.Database.CanConnectAsync(cancellationToken)?HealthCheckResult.Healthy("Security Operations SQL Server is reachable."):HealthCheckResult.Unhealthy("Security Operations SQL Server is not reachable.");}catch(Exception ex){return HealthCheckResult.Unhealthy("Security Operations SQL Server readiness check failed.",ex);}}}